using LocalChat;
using System.Text.Json;
int passed=0;void Check(bool ok,string n){if(!ok)throw new Exception(n);passed++;Console.WriteLine("PASS "+n);}void Reject(Action a,string n){try{a();}catch{Check(true,n);return;}throw new Exception(n);}
string root=Path.GetFullPath(args[0]);var models=PeftCatalog.Models;Check(models.Length==16,"embedded catalog has exactly 16 real adapters");Check(models.All(m=>m.Likes>0),"nonzero likes");Check(models.All(m=>m.Base==PeftCatalog.BaseId),"all use exact Instruct base, not Base or GGUF");Check(models.Select(m=>m.Id).Distinct().Count()==16,"unique IDs");Check(models.Select(m=>PeftCatalog.Home(root,m)).Distinct().Count()==16,"isolated stable caches");Check(models.All(m=>m.Files.Any(f=>f.Name=="adapter_model.safetensors")),"all entries contain actual weights");Check(models.All(m=>m.Files.All(f=>!f.Name.EndsWith(".py")&&!f.Name.EndsWith(".pt")&&!f.Name.EndsWith(".bin"))),"no repo code or unsafe serialization");Reject(()=>PeftCatalog.Get("../../fake"),"unknown ID blocked");Check(models.All(m=>!PeftCatalog.Present(Path.Combine(root,"not-downloaded-test"),m)),"catalog does not pretend weights installed");var settings=new Settings{Mode=3,PeftAdapterId=models[0].Id};var restored=JsonSerializer.Deserialize<Settings>(JsonSerializer.Serialize(settings,Disk.Json),Disk.Json)!;Check(restored.Mode==3&&restored.PeftAdapterId==settings.PeftAdapterId,"selected adapter persists across sessions");
string program=File.ReadAllText(Path.Combine(root,"src/Program.cs")),tools=File.ReadAllText(Path.Combine(root,"src/AgentLoop.cs")),manager=File.ReadAllText(Path.Combine(root,"src/PeftManager.cs"));Check(program.Contains("else if(settings.Mode is 0 or 3)answer=await AirReply"),"normal generation dispatches PEFT");Check(tools.Contains("settings.Mode is 0 or 3?await AirReply"),"browser/tool conversation dispatches PEFT");Check(program.Contains("if(settings.Mode==3)return await PeftReply"),"PEFT dispatcher reaches actual backend");Check(program.Contains("next.PeftAdapterId=settings.PeftAdapterId"),"settings form preserves adapter selection");Check(manager.Contains("if(!committed){settings=previous;"),"failed installation restores settings");Check(manager.Contains("process.Kill(true)"),"setup cancellation kills child process tree");Check(manager.Contains("StopAir();StopServer();"),"runtime switching stops old engines");Check(manager.Contains("--only-binary=:all:"),"runtime setup forbids dependency source builds");Check(manager.Contains("settings.ContextTokens=2048;settings.MaxTokens=512"),"conservative first-use context");Console.WriteLine($"{passed} PEFT host checks passed");
